package com.masaakis.addonfeature.api;import com.masaakis.addonfeature.application.ProductAddonService;import com.masaakis.security.StaffPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController@RequestMapping("/api/admin/features")public class ProductAddonController{private final ProductAddonService s;public ProductAddonController(ProductAddonService x){s=x;}@GetMapping ProductAddonService.Settings settings(@AuthenticationPrincipal StaffPrincipal p){return s.settings(p);}@PostMapping("/branches")Map<String,UUID>branch(@AuthenticationPrincipal StaffPrincipal p,@Valid@RequestBody Name r){return Map.of("id",s.createBranch(p,r.name));}@PostMapping("/branches/{id}/switch")ResponseEntity<Void>switchBranch(@AuthenticationPrincipal StaffPrincipal p,@PathVariable UUID id){s.switchBranch(p,id);return ResponseEntity.noContent().build();}@PutMapping("/branding")ResponseEntity<Void>brand(@AuthenticationPrincipal StaffPrincipal p,@Valid@RequestBody ProductAddonService.Brand r){s.branding(p,r);return ResponseEntity.noContent().build();}@PutMapping("/translations/{locale}")ResponseEntity<Void>translate(@AuthenticationPrincipal StaffPrincipal p,@PathVariable String locale,@Valid@RequestBody Translation r){s.translate(p,locale,r.menuId,r.menuName,r.menuDescription,r.categories,r.products);return ResponseEntity.noContent().build();}@GetMapping("/reports")ProductAddonService.Report report(@AuthenticationPrincipal StaffPrincipal p,@RequestParam LocalDate from,@RequestParam LocalDate to){return s.report(p,from,to);}public record Name(@NotBlank@Size(max=140)String name){}public record Translation(@NotNull UUID menuId,@NotBlank@Size(max=140)String menuName,@Size(max=500)String menuDescription,List<ProductAddonService.CategoryText>categories,List<ProductAddonService.ProductText>products){}}
